  Notation MW := [(SP - AHUF_FAST_ARGS_STACK, SP); (A, A + 152)].


  (* [comment removed for export] *)
  Ltac afa_facts :=
    pose proof (afa_sp0 sp lo A LOA LOS ASP A47) as SPB;
    pose proof (bv_unsigned_in_range 64 sp) as RSP; unfold bv_modulus in RSP; cbn in RSP;
    pose proof (afa_kshz m0 rstk A 152 RCL RLO RHI A8 eq_refl ltac:(lia)) as KSH;
    pose proof ART as (RG0 & RGOT & RGRIC & RMEM & RSHB & _);
    assert (RGOT' : rw_cells asegs m0 0xaf758 [C8 (Z_to_bv 64 0x1494e8); C8 (Z_to_bv 64 0xb51b8); C8 (Z_to_bv 64 0xb79b8);
                                              C8 (Z_to_bv 64 0xb86a8); C8 (Z_to_bv 64 0xb86b0); C8 (Z_to_bv 64 0xb86a0)]) by exact RGOT;
    assert (RSHB' : rw_cells asegs m0 0xb79b8 [C8 (Z_to_bv 64 0x7fff8000)]) by exact RSHB;
    clear RG0 RGOT RGRIC RMEM RSHB;
    assert (FAP : KXGoM.apart (SP - 48) 48 0x7fff8000 17592186044416) by (unfold KXGoM.apart; lia);
    assert (AAP : KXGoM.apart A 152 0x7fff8000 17592186044416) by (unfold KXGoM.apart; lia);
    unfold AHUF_FAST_ARGS_STACK in *.

  (* [comment removed for export] *)
  Lemma afa_ret : forall mm r cs (t0 t1 t2 a1 a2 a3 a4 a5 a7 t3 t4 t5 t6 x9 x18 x19 x8 : word),
    rw_cells asegs mm (SP + -40) [C8 s3] -> rw_cells asegs mm (SP + -32) [C8 s2] -> rw_cells asegs mm (SP + -24) [C8 s1] ->
    rw_cells asegs mm (SP + -16) [C8 s0] -> rw_cells asegs mm (SP + -8) [C8 ra] ->
    rw_cells asegs mm A cs -> cells_size cs = 152%nat ->
    stk asegs mm lo (SP + -40) -> mem_inv asegs mm -> munch [(SP - 48, SP); (A, A + 152)] m0 mm -> wmono asegs m0 mm ->
    0 <= r < 2^64 -> (r = 0 \/ r = 2^64 - 20 \/ (r = 1 /\ fast_args_okA mm A DST dcap S DT src tl)) ->
    evtF asegs RNG POST (MS (mkR ra (Z_to_bv 64 (SP + -48)) gp tp t0 t1 t2 x8 x9 (Z_to_bv 64 A) a1 a2 a3 a4 a5 (Z_to_bv 64 r) a7
                                 x18 x19 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                           F (Z_to_bv 64 0x94290) fc None mm (seg_rom asegs)).
