  (* [comment removed for export] *)
  Definition AFA_E20 : Prop :=
    forall mm (w0 w1 w2 w3 w4 w5 w6 w7 w8 w9 w10 w11 w12 w13 w14 : word) (I0 I1 I2 I3 : Z) (t0 t1 t3 t4 x9 a6 a7 : word),
    I0 = S + 6 -> I1 = I0 + jt_len src 0 -> I2 = I1 + jt_len src 2 -> I3 = I2 + jt_len src 4 ->
    8 <= jt_len src 0 -> 8 <= jt_len src 2 -> 8 <= jt_len src 4 -> I3 + 8 <= S + n -> 1 <= dcap ->
    rw_cells asegs mm (SP + -40) [C8 s3] -> rw_cells asegs mm (SP + -32) [C8 s2] -> rw_cells asegs mm (SP + -24) [C8 s1] ->
    rw_cells asegs mm (SP + -16) [C8 s0] -> rw_cells asegs mm (SP + -8) [C8 ra] ->
    rw_cells asegs mm A [C8 w0; C8 w1; C8 w2; C8 w3; C8 w4; C8 w5; C8 w6; C8 w7; C8 w8; C8 w9; C8 w10; C8 w11; C8 w12; C8 w13;
                         C8 w14; C8 (Z_to_bv 64 I0); C8 (Z_to_bv 64 I1); C8 (Z_to_bv 64 I2); C8 (Z_to_bv 64 I3)] ->
    bytes_at asegs mm S (map (Z_to_bv 8) src) ->
    stk asegs mm lo (SP + -40) -> mem_inv asegs mm -> munch [(SP - 48, SP); (A, A + 152)] m0 mm -> wmono asegs m0 mm ->
    evtF asegs RNG POST (MS (mkR ra (Z_to_bv 64 (SP + -48)) gp tp t0 t1 (Z_to_bv 64 2147450880) (Z_to_bv 64 I1) x9
                               (Z_to_bv 64 A) (Z_to_bv 64 DST) (Z_to_bv 64 dcap) (Z_to_bv 64 S) (Z_to_bv 64 n) (Z_to_bv 64 DT)
                               a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 (Z_to_bv 64 I3) (Z_to_bv 64 I2))
                           F (Z_to_bv 64 0x940fc) fc None mm (seg_rom asegs)).

  Ltac afa_jtl := unfold jt_len; change (0 + 1) with 1; change (2 + 1) with 3; change (4 + 1) with 5; lia.

  (* [comment removed for export] *)
  Ltac afa_exit r :=
    lazymatch goal with |- evtF _ _ _ (MS _ _ _ _ _ ?mm _) =>
      eapply (afa_ret mm r [C8 _; C8 _; C8 _; C8 _; C8 _; C8 _; C8 _; C8 _; C8 _; C8 _; C8 _; C8 _; C8 _; C8 _; C8 _; C8 _;
                            C8 _; C8 _; C8 _]);
      [ eassumption | eassumption | eassumption | eassumption | eassumption | kx_cells_merge | reflexivity
      | eassumption | eassumption | eassumption | eassumption | lia | first [left; lia | right; left; lia] ]
    end.

  Lemma afa_jt : AFA_E20 -> forall (t0 t1 t3 t4 t5 t6 : word), tl = 11 -> 1 <= dcap -> 10 <= n -> forall mm (x16 x17 : word),
    rw_cells asegs mm (SP + -40) [C8 s3] -> rw_cells asegs mm (SP + -32) [C8 s2] -> rw_cells asegs mm (SP + -24) [C8 s1] ->
    rw_cells asegs mm (SP + -16) [C8 s0] -> rw_cells asegs mm (SP + -8) [C8 ra] ->
    rw_cells asegs mm A [CB 152 ja] -> bytes_at asegs mm S (map (Z_to_bv 8) src) ->
    stk asegs mm lo (SP + -40) -> mem_inv asegs mm -> munch [(SP - 48, SP); (A, A + 152)] m0 mm -> wmono asegs m0 mm ->
    evtF asegs RNG POST (MS (mkR ra (Z_to_bv 64 (SP + -48)) gp tp t0 t1 (Z_to_bv 64 2147450880) s0 s1 (Z_to_bv 64 A)
                               (Z_to_bv 64 DST) (Z_to_bv 64 dcap) (Z_to_bv 64 S) (Z_to_bv 64 n) (Z_to_bv 64 DT) x16 x17
                               s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                           F (Z_to_bv 64 0x93fb8) fc None mm (seg_rom asegs)).
